-- 004: 'When to expect it' lifespan section
update guides set content = $j${"id": "cam-follower", "title": "Cam follower inspection & replacement", "fits": "2006 VW GTI · 2.0T FSI (BPY)", "alsoFits": "2006–09 GTI · 06–08 Jetta 2.0T · 06–08 Passat 2.0T · 07+ Eos · 06–08 A3 · 12–13 Golf R", "category": "Engine", "glance": {"timeFirst": "1–2 hr", "timeRepeat": "30–45 min", "difficulty": 2.5, "cost": "$25–70", "risk": "Pressurized fuel · soft aluminum threads", "why": "This $25 cup wears through, then destroys a $400 fuel pump and a $1,000+ camshaft.", "note": {"text": "Four sources ranged 30 min to 2 hr. The banjo bolt in step 6 is where first-timers lose an hour.", "only": ["stock"]}, "noteAlt": null}, "heroCap": "The pump piston rides on a small steel cup, and the cup rides on the cam. The cup is designed to wear so the cam doesn't. When the cup is gone, the cam does.", "should": {"yesIf": ["You don't know when it was last checked", "10,000+ miles since the last check", {"text": "It's been a full oil change since you last looked", "only": ["upgraded"]}, "Power cuts under boost, stumbles, misfires"], "codes": ["P0087", "P0089", "P1093", "P2293", "P2294"], "notes": ["Early wear has no symptoms. Owners have pulled followers worn through the coating with no check-engine light.", "Read “don't replace it, let VW cover it” somewhere? That was VW's 10-yr/120k-mile extension. For a 2006 car it expired years ago. Replace it.", {"text": "Upgraded pumps push harder on the follower, and owners running them report faster wear. Treat the follower as an every-oil-change check, not a 10–20k item.", "only": ["upgraded"]}], "confidence": {"level": "high", "n": 4, "note": "Symptoms and codes agree across ECS, FCP Euro and multiple forum reports."}}, "parts": [{"tier": "oe", "name": "Cam follower, Genuine VW", "pn": "06D109309C → 06D109309J", "note": "Same part as the INA below, in a VW box", "price": "$45–60", "links": [{"store": "FCP Euro (Genuine)", "url": "https://www.fcpeuro.com/products/audi-volkswagen-fuel-pump-cam-follower-oes-genuine-06d109309c"}]}, {"tier": "oem", "name": "Cam follower, INA", "pn": "06D109309C", "note": "INA makes the factory part. Same follower, half the price", "price": "$25", "links": [{"store": "ECS Tuning (INA)", "url": "https://www.ecstuning.com/b-ina-parts/fuel-pump-cam-follower-06d109309c/06d109309c~ina/"}]}, {"tier": "oem", "name": "Follower kit (follower + o-ring + bolts)", "pn": "06D109309CKT", "note": "Everything in one box", "price": "$45–70", "links": [{"store": "ECS Tuning", "url": "https://www.ecstuning.com/b-assembled-by-ecs-parts/cam-follower-replacement-kit/06d109309ckt/"}]}, {"tier": "oe", "name": "HPFP o-ring", "pn": "in kit", "note": "Old one is usually heat-hardened", "price": "in kit", "links": []}], "tools": [{"name": "T30 Torx on ¼\" drive", "note": "one bolt is too tight for ⅜\"", "price": "$8–15"}, {"name": "M8 triple-square (XZN) stubby bit + 13mm box wrench", "note": "only if you have the banjo bolt (most 2006 cars)", "price": "$10–20"}, {"name": "17mm open-end or flare-nut wrench", "price": "$10"}, {"name": "13mm wrench", "price": "$8"}, {"name": "Torque wrench accurate at 10 Nm", "note": "an inch-pound ¼\" wrench, not a ½\" click wrench", "price": "$40–80"}, {"name": "Small flat screwdriver, rags, safety glasses, assembly lube", "price": "$15"}], "before": ["Engine cold. You're opening the fuel system next to the exhaust side.", "Safety glasses on before step 2. The pump runs at 30–110 bar (435–1,600 psi).", "Anything that falls into the open pump bore falls into your cylinder head. Rag over nearby openings.", "Check which low-pressure fitting you have (bottom of the pump). Metal line held by a small bolt = banjo. Rubber hose on a barbed brass fitting = barb."], "steps": [{"n": 1, "title": "Remove the engine cover", "blocks": [{"t": "text", "b": "Unplug the connector at the back of the cover, release the intake-hose clip, pull the hose off, then grab both sides and wiggle the cover straight up off its grommets."}]}, {"n": 2, "title": "Bleed the fuel pressure", "blocks": [{"t": "text", "b": "Unplug the connector on top of the pump (the pressure regulator). Start the engine and let it run about 10 seconds. It will sputter; that's expected."}, {"t": "text", "b": "Shut it off. Rag over the brass test port on the pump body, remove its black cap, and slowly loosen the port with a 13mm until residual fuel weeps out. Remove it fully; you want it out of the way for step 7 anyway."}, {"t": "warn", "b": "Fuel will still be present. Expect a few tablespoons when the lines come off."}, {"t": "conf", "c": {"level": "community", "n": 3, "note": "Three sources, three variations. All work. None cites the factory procedure."}}]}, {"n": 3, "title": "Unplug and clear the area", "blocks": [{"t": "text", "b": "Unplug the second connector on the side of the pump (pressure sensor; a small flat screwdriver releases the tab). If the PCV/vacuum fitting is in the way, unclip it at its four corners and move it aside. You do not need to remove the main PCV hose."}]}, {"n": 4, "title": "Rag under the pump", "blocks": [{"t": "text", "b": "Fuel will drip onto the head. The rag also catches anything you drop."}]}, {"n": 5, "title": "Loosen the high-pressure hard line", "blocks": [{"t": "text", "b": "17mm on the collar nut where the metal line meets the pump. Slide the collar back. Don't bend or lever the line; the fittings are brass."}]}, {"n": 6, "title": "Remove the low-pressure fitting", "timeSink": true, "blocks": [{"t": "fork", "q": "Which fitting do you have?", "v": [{"label": "Banjo bolt", "when": "Most 2006 cars", "blocks": [{"t": "text", "b": "Seat the stubby M8 triple-square in the bolt head and turn it with a box wrench on the bit's shank. Tape around the bit keeps it in the wrench. Fine threads into brass: go slow."}, {"t": "ill", "id": "banjo", "cap": "Stubby bit in the bolt head, wrench on the bit. If the bit walks out of the head, stop and re-seat it; a rounded head here is a bad day."}, {"t": "embed", "id": "wBCHQCF6si4", "title": "See the banjo bolt", "note": "AskDAP answers a 2006 GLI owner asking how to get rid of this fitting"}]}, {"label": "Barbed fitting", "when": "2008+, or converted", "blocks": [{"t": "text", "b": "Squeeze the spring clamp and slide the rubber hose off the barb."}]}]}, {"t": "note", "b": "This is the step that turns a 45-minute job into a 2-hour one. Several owners eventually convert to the barbed style ($50–250 in parts) so they never fight this bolt again."}]}, {"n": 7, "title": "Remove the three T30 pump bolts", "blocks": [{"t": "text", "b": "With the test port already out, the lowest bolt is reachable. Use ¼\" drive for the tight one. Loosen all three evenly."}]}, {"n": 8, "title": "Pull the pump", "blocks": [{"t": "text", "b": "Wiggle it straight out. If the o-ring has hardened it may stick; tap the pump body gently with a plastic mallet. Do not pry against the head. Set it down piston-end up."}, {"t": "warn", "b": "The cam is now exposed. Nothing goes in that hole except your fingertip and the new follower."}]}, {"n": 9, "title": "Remove the old follower", "blocks": [{"t": "text", "b": "Reach in with a fingertip and slide the cup out. Look at it now (see Reading your old follower below), then look at the cam lobe with a light and mirror, and at the end of the pump piston."}, {"t": "note", "b": "With a high-flow pump, don't be surprised to find the coating worn through at half the mileage a stock car would show it. That's the pump doing its job, not a defective follower.", "only": ["upgraded"]}]}, {"n": 10, "title": "Install the new follower", "blocks": [{"t": "text", "b": "Oil the outside of the cup and put a generous smear of assembly lube on its face. Slide it into the bore, open side toward the pump. A dab of lube on the cam lobe is cheap insurance against a dry start."}]}, {"n": 11, "title": "New o-ring on the pump", "blocks": [{"t": "text", "b": "Pull the old o-ring from the pump's groove, clean the groove, fit the new one. Wipe the pump's mating face and the bore area on the head."}]}, {"n": 12, "title": "Install the pump", "caution": true, "blocks": [{"t": "note", "b": "Upgraded pumps use the same three T30 bolts and the same 10 Nm. Some kits ship longer bolts with a spacer; if yours did, use the kit's bolts and its torque sheet.", "only": ["upgraded"]}, {"t": "text", "b": "Check the cam lobe. If its peak is pointing at the follower, the pump needs a lot of force to seat and the bolts start under load. You want the flat flank. If it's on the nose, either push the pump down firmly and squarely while starting the bolts, or bump the crank pulley slightly to rotate it off."}, {"t": "ill", "id": "lobe", "cap": "Left is what you want. Right works, but you're fighting the spring and it's easy to cross-thread a bolt while pushing."}, {"t": "text", "b": "Press the pump squarely into the bore so the spring compresses, then start all three bolts by hand. Tighten them alternately, a little at a time, so the pump draws down evenly."}, {"t": "torque", "label": "HPFP mounting bolts (T30 ×3)", "nm": 10, "c": {"level": "high", "n": 5, "note": "10 Nm / 7–7.5 lb-ft agrees across ECS, FCP Euro, MyFastGTI and three VWVortex threads."}}, {"t": "warn", "b": "10 Nm is barely more than a firm hand-tightening. These bolts thread into soft aluminum. Over-torque strips the head, and now you're helicoiling a cylinder head with a fuel pump hanging off it. No torque wrench that reads 10 Nm? Stop and get one."}]}, {"n": 13, "title": "Reinstall the low-pressure fitting", "blocks": [{"t": "fork", "q": "Which fitting do you have?", "v": [{"label": "Banjo bolt", "when": "Most 2006 cars", "blocks": [{"t": "text", "b": "Bolt and brass threads spotless and burr-free. Thread it in by hand at least 4–5 full turns before touching a wrench. If it doesn't spin freely, back it out and start again: it's cross-threaded. No sealing washers on this fitting."}, {"t": "torque", "label": "Banjo bolt", "nm": 17, "c": {"level": "single", "n": 1, "note": "One source for this value. Thread cleanliness matters more than the number."}}]}, {"label": "Barbed fitting", "when": "2008+, or converted", "blocks": [{"t": "text", "b": "Push the hose fully onto the barb and reseat the spring clamp."}]}]}]}, {"n": 14, "title": "Reinstall the high-pressure hard line", "blocks": [{"t": "text", "b": "Thread the 17mm collar on and tighten. In practice: snug with a wrench until it won't weep."}, {"t": "torque", "label": "Hard-line collar nut (17mm)", "nm": 25, "alt": [27], "c": {"level": "varies", "n": 2, "note": "25 Nm vs 27 Nm. Neither is from a factory manual."}}]}, {"n": 15, "title": "Test port, connectors, hoses", "blocks": [{"t": "text", "b": "Reinstall the brass test port (13mm, snug) and its cap. Reconnect both connectors and any vacuum/PCV fitting you moved."}]}, {"n": 16, "title": "Start and check for leaks", "blocks": [{"t": "text", "b": "It may stumble for a few seconds while pressure builds. Look and smell for fuel at the banjo, the hard-line collar and the test port. Anything weeps: shut off and re-seat that fitting. Clear codes."}]}, {"n": 17, "title": "Engine cover back on", "blocks": [{"t": "text", "b": "Reverse step 1. Drive it. A stumble that persists beyond a few minutes means recheck the connectors."}]}], "check": {"tab": "Read the wear", "title": "Reading your old follower", "illId": "wear", "illCap": "Face-on, as you'll see it in your hand. B is where most people find theirs.", "rows": [{"see": "Black coating intact, maybe faint scuffing", "means": "Normal. The anti-wear coating is doing its job.", "do": "Reinstall or replace (it's cheap). Check again in 10–20k."}, {"see": "Silver showing through the black in the center", "means": "Coating gone; base metal wearing. Where most followers are found at 50–80k.", "do": "Replace. Check the cam lobe: smooth and shiny means you're fine."}, {"see": "Concave, worn through, or in pieces", "means": "Late-stage failure. The pump piston has been riding the cam.", "do": "Replace, and inspect cam lobe + pump piston for scoring. Scored lobe = camshaft. Galled piston = pump. Change the oil."}], "c": {"level": "medium", "n": 4, "note": "Rubric consistent across ECS, FCP Euro and owner photos on two forums."}}, "aftercare": ["No factory inspection interval exists. VW's schedule never listed it.", {"text": "Community consensus: inspect every 10,000–20,000 miles (every oil change or every other).", "only": ["stock"]}, {"text": "Community consensus for upgraded pumps: inspect every oil change, and keep a spare follower in the glovebox. They're $25.", "only": ["upgraded"]}, "Second time is a 30–45 minute job. Consider converting the banjo to the barbed fitting.", "Keep your oil level up. Whatever the root cause, a dry follower dies faster."], "disagreements": [{"topic": "Does the banjo bolt exist?", "pos": "FCP Euro's guide never mentions it; three other sources spend the most words on it.", "call": "Their car had the later fitting. 2006 cars: assume banjo."}, {"topic": "Hard-line torque", "pos": "25 Nm vs 27 Nm.", "call": "Show the range, flag as non-factory."}, {"topic": "Inspection interval", "pos": "“Every 10k” vs “every 10k is overkill” vs “not a service item.”", "call": "10–20k; 10k if tuned."}, {"topic": "Replace, or wait for warranty?", "pos": "A 2013 thread said wait and let VW pay.", "call": "Extension expired for 2006 cars. Replace."}, {"topic": "Root cause", "pos": "Soft cam vs low-ZDDP US oil vs bad design.", "call": "VW revised the cam three times and extended the warranty; that's what's verifiable. Oil theory unproven."}, {"topic": "Triple-square size", "pos": "M8 (three sources) vs M5 (one).", "call": "M8."}], "sources": ["FCP Euro DIY (2022, Humble Mechanic)", "ECS Tuning blog DIY (2017)", "MyFastGTI DIY thread (2010–14)", "VWVortex: torque spec, stripped threads, early replacement, INA roller, “stop replacing”", "DAP: cam revisions, banjo conversion", "Audi-Sport.net banjo cutover", "markFive GTI warranty letters", "Audi TT Forum owner reports", "ECS product listings"], "embeds": [{"id": "5CD6obyhZmg", "note": "Humble Mechanic for FCP Euro, 2022. His car has the later hose fitting, so his step 3 skips the banjo bolt you probably have."}, {"id": "wBCHQCF6si4", "note": "AskDAP — the banjo bolt question"}], "variants": {"question": "Which fuel pump is on your car?", "hint": "The high-pressure pump sits on top of the engine at the back. A factory or OEM replacement pump is black with a VW/Hitachi marking. Upgraded pumps (APR, Autotech, and others) usually came with a tune and often have a machined or anodized top.", "options": [{"id": "stock", "label": "Stock or OEM replacement", "when": "Never changed, or replaced with a factory-style pump"}, {"id": "upgraded", "label": "Upgraded high-flow pump", "when": "APR, Autotech or similar, typically on a Stage 2+ tune"}]}, "aftermarket": [{"name": "Coated 'upgraded' followers", "note": "A few specialists sell followers with a thicker or different anti-wear coating. Forum reports are mixed and the factory part is cheap, so most owners stay OEM.", "price": "$60–120", "signal": "Community verdict: skip, buy INA", "links": []}, {"name": "Roller-follower conversion (TSI-style)", "note": "Replaces the flat follower with the roller design VW used on the later TSI. Involved install, documented on VWVortex; for people who want the wear problem gone for good.", "price": "$150+", "signal": "Enthusiast option", "links": []}], "lifespan": {"title": "When to expect it", "headline": [{"text": "Coating typically worn through between 50,000 and 80,000 miles", "only": ["stock"]}, {"text": "With a high-flow pump, expect it in half that: 25,000 to 40,000 miles", "only": ["upgraded"]}], "earliest": "Earliest failures reported around 15,000 miles on early (2006) camshafts", "detail": "Owner photos cluster around 65–70k for a follower that's silver in the middle but still flat. Past 85k on an unchecked car, worn-through and concave followers become common.", "factors": ["Upgraded HPFP or Stage 2+ tune", "Early 'A' revision camshaft (2006)", "Low oil level", "Never inspected"], "inspect": [{"text": "Inspect every 10,000–20,000 miles", "only": ["stock"]}, {"text": "Inspect every oil change", "only": ["upgraded"]}], "confidence": {"level": "community", "n": 9, "note": "Nine owner reports with photos across three forums, plus two vendor notes. No factory interval exists."}}}$j$::jsonb, updated_at = now() where id = 'cam-follower';
update guides set content = $j${"id": "sway-rear", "title": "Rear sway bar upgrade", "fits": "2006 VW GTI · multilink rear", "alsoFits": "2006–09 GTI/Rabbit (multilink) · 06–08 Jetta · 06–08 A3 8P FWD · 08+ TT 8J FWD · Mk6 GTI/Golf", "category": "Suspension", "kind": "upgrade", "glance": {"timeFirst": "1–2 hr", "timeRepeat": "45 min", "difficulty": 2, "cost": "$200–350", "risk": "Car on jack stands · exhaust clearance", "why": "Your GTI understeers because VW wanted it to. A stiffer rear bar hands some of that grip back to the front, so the car turns in sharper and stays flatter, without touching the ride.", "note": "Manufacturer guides say about 2 hours; owners report closer to 1. Wrestling the bar past the exhaust is the variable."}, "heroCap": "Looking up from under the rear of the car. The bar bolts to the subframe in two brackets and reaches each side through a short end link. Stock is 21.7 mm; upgrades run 24–27 mm.", "should": {"yesIf": ["The car pushes wide (understeers) in fast corners and you'd like it more neutral", "You've done tires and want the next real handling step", "You want a mod you can feel on the first drive", "You'd rather not change springs or dampers yet"], "codes": [], "notes": ["Rear-only is the classic first move on a front-wheel-drive car: the front already has plenty of roll stiffness from doing all the work, so stiffening the rear is what shifts the balance. Upgrading the front too mostly adds flatness, not balance.", "Trade-offs: a stiffer rear bar lifts the inside rear wheel sooner in hard cornering, and mid-corner bumps hit both sides. On all-season tires in the rain, the stiffest setting can make the tail livelier than you want."], "confidence": {"level": "high", "n": 4, "note": "Consistent across manufacturer descriptions, forum consensus, and basic vehicle dynamics."}}, "parts": [{"tier": "aftermarket", "name": "Rear sway bar kit (bar, bushings, hardware)", "pn": "see options below", "note": "Adjustable (two-hole) bars let you tune it later", "price": "$200–350", "links": []}, {"tier": "oe", "name": "Bracket bolts, M8 (×4)", "pn": "factory", "note": "Torque-to-yield style spec; new ones are cheap", "price": "$8", "links": []}, {"tier": "oe", "name": "End link nuts (×2)", "pn": "factory", "note": "Reusable, but replace if the nylon insert is tired", "price": "$4", "links": []}], "tools": [{"name": "Jack + two jack stands (or ramps)", "note": "final torque happens with the car on its wheels", "price": "$80–150"}, {"name": "10mm triple-square (XZN) bit", "note": "bracket bolts; decent quality, not a bargain-bin set", "price": "$10"}, {"name": "6mm triple-square bit", "note": "holds the end-link stud; it never turns anything", "price": "$8"}, {"name": "16mm wrench + 15mm wrench", "price": "$20"}, {"name": "Torque wrench, 20–60 Nm range", "price": "$40–80"}, {"name": "Poly bushing grease (if the kit's is stingy), tape or towels to protect the bar's finish", "price": "$10"}], "before": ["Level ground, wheels chocked, car in gear or Park. Jack stands on the rear jack points, never the subframe alone.", "Exhaust cold. You'll have your arms around it.", "Check the kit: bar, two bushings, two brackets (if supplied), hardware. Read the kit's sheet; where it gives its own torque values for its own hardware, those win.", "US 2006 GTIs have the multilink rear this guide covers. If your car has a solid beam axle (some base Golfs in other markets), this bar won't fit."], "steps": [{"n": 1, "title": "Raise the rear and support it", "blocks": [{"t": "text", "b": "Jack the rear and set both stands. Wheels can stay on; you're working inboard of them. A creeper or piece of cardboard makes the next hour nicer."}]}, {"n": 2, "title": "Disconnect the end links from the bar", "blocks": [{"t": "text", "b": "Each end of the bar has a short link with a stud through it. Put the 6mm triple-square into the stud's socket to hold it still, and turn the 16mm nut off. There's no room for a ratchet by the caliper; a wrench is fine, the nut isn't very tight."}, {"t": "ill", "id": "endlink", "cap": "The bit only holds the stud. If you try to turn the bit, it strips. Turn the nut."}, {"t": "warn", "b": "The bar is not under load. Nothing springs when the links come off."}]}, {"n": 3, "title": "Swing the bar free of the links", "blocks": [{"t": "text", "b": "Rotate the bar so each end drops out of its link. Leave the links attached to the trailing arms."}]}, {"n": 4, "title": "Unbolt the two brackets", "blocks": [{"t": "text", "b": "Two bolts per bracket into the subframe, 10mm triple-square. Support the bar as the last bolt comes out; it's heavier than it looks."}]}, {"n": 5, "title": "Wrangle the old bar out", "timeSink": true, "blocks": [{"t": "text", "b": "The bar has to rotate around the exhaust to clear. Turn it, tip it, and feed it out one side. If it won't go, loosen the rear muffler hangers (two bolts) to gain an inch of drop."}, {"t": "note", "b": "Pull the old bushings and brackets off it now if you're reusing them. Compare old and new bars side by side; the arm shape should match."}]}, {"n": 6, "title": "Bushings onto the new bar", "blocks": [{"t": "text", "b": "Grease the inside of each bushing with the supplied poly grease (not petroleum grease, which swells polyurethane). Slide them onto the bar at the same positions as the old ones, then set the brackets over them."}, {"t": "note", "b": "Powder coat scratches easily. Leave the plastic wrap on the bar until it's up in the car."}]}, {"n": 7, "title": "Feed the new bar in", "blocks": [{"t": "text", "b": "Reverse of step 5. Get the brackets up to the subframe and start all four bolts by hand. Snug, don't torque, so the bar can still rotate."}]}, {"n": 8, "title": "Pick your setting and connect the links", "blocks": [{"t": "fork", "q": "Which hole?", "v": [{"label": "Forward (softer)", "when": "Start here", "blocks": [{"t": "text", "b": "Roughly double the stock bar's rate on a 25mm bar. A clear step up in turn-in and flatness with no drama. Drive it a week before you decide you want more."}]}, {"label": "Rearward (stiffer)", "when": "Sticky tires, track days", "blocks": [{"t": "text", "b": "About 2.5× stock on a 25mm bar. Sharper still, with more inside-rear wheel lift and a livelier tail in the wet. Common second step, rare first one."}]}]}, {"t": "text", "b": "Rotate the bar so the chosen hole lines up with each end-link stud, pass the stud through, and start the nuts. Snug only."}]}, {"n": 9, "title": "Lower the car, then torque everything", "caution": true, "blocks": [{"t": "text", "b": "The factory manual says these fasteners get their final torque with the car sitting on its wheels, not hanging on stands. Otherwise the bushings and links are clamped at the wrong angle and you get clunks and early bushing wear. Lower onto ramps, or onto the ground and reach under."}, {"t": "torque", "label": "Bracket bolts (M8, ×4) · factory hardware", "nm": 25, "c": {"level": "single", "n": 1, "note": "Bentley manual value via TDIClub: 25 Nm then a further 45° turn. If your kit supplied its own brackets and bolts, use the kit's number (034: 25 Nm flat, with Loctite)."}, "note": "+45° turn"}, {"t": "torque", "label": "End link nuts (M10, ×2)", "nm": 45, "alt": [35], "c": {"level": "varies", "n": 2, "note": "45 Nm is the factory value for factory hardware. 35 Nm is what 034 specifies for its own nylock hardware. Follow whichever hardware you're actually tightening."}}, {"t": "warn", "b": "A forum regular guessed 50 lb-ft (68 Nm) on these and stretched the bolts. Both fasteners are smaller than they feel. Use the wrench."}]}, {"n": 10, "title": "Test drive and re-check", "blocks": [{"t": "text", "b": "Drive 20–50 miles with a few firm corners, then re-torque all six fasteners. Clunking over one-wheel bumps means a bracket or link is loose or the bushing wasn't greased."}]}], "check": {"tab": "Pick a setting", "title": "Which setting is right for you?", "illId": "setting", "illCap": "Both holes are on the same bar. Closer to the pivot is stiffer because the lever is shorter.", "rows": [{"see": "Daily driver, all-season tires", "means": "You want turn-in and less lean, not a tail that steps out in the rain.", "do": "Forward hole. Most people never move it."}, {"see": "Summer tires, spirited driving", "means": "The chassis can use more rear roll stiffness before it gets nervous.", "do": "Start forward, try rearward after a week. Expect more inside-wheel lift."}, {"see": "Autocross or track", "means": "Balance matters more than comfort, and you'll adjust per event.", "do": "Rearward, and consider adjustable end links so both sides preload evenly."}], "c": {"level": "community", "n": 3, "note": "Forum consensus plus manufacturer stiffness figures. There is no factory guidance; this is a preference."}}, "aftercare": ["Re-torque after the first 20–50 miles, then forget about it.", "A squeak on slow speed bumps is a dry bushing. Some brackets have a grease port; otherwise pull the bracket and re-grease.", "Adjustable end links are the usual next step if you go to the stiff hole: they let you remove preload so the bar isn't twisted at rest."], "disagreements": [{"topic": "End link torque", "pos": "45 Nm (factory) vs 35 Nm (034's hardware) vs 55 Nm (Mk7 guides).", "call": "45 for factory hardware, kit value for kit hardware. Mk7 numbers are a different car and excluded."}, {"topic": "Torque on stands or on the ground?", "pos": "Manufacturer PDFs torque on the lift; the factory manual says curb weight.", "call": "Snug in the air, final torque on the wheels."}, {"topic": "Which hole first?", "pos": "“Full stiff rear” vs “start soft.”", "call": "Start soft. It's a two-minute change later."}, {"topic": "Front bar too?", "pos": "Some do both.", "call": "Rear first. On a FWD car it's the balance change; the front is mostly flatness."}], "sources": ["034Motorsport install guide (Mk5/6 FWD)", "Pelican Parts Mk5 GTI rear stabilizer DIY", "TDIClub torque thread citing the Bentley manual", "VWVortex APR 27mm install thread", "GolfMKV H&R 22mm install thread", "Neuspeed product data (stiffness by hole)", "Owner reviews (exhaust clearance, finish)"], "embeds": [{"id": "S8KnvgU-MLQ", "note": "ECS Tuning on a Mk5/Mk6. Same rear subframe and brackets as your car."}, {"id": "2ts5lTilGiM", "note": "034 install and the why-upgrade case"}], "aftermarket": [{"name": "Neuspeed 25mm, adjustable", "note": "Tubular, red, two-hole. Forward hole ≈2× stock, rearward ≈2.5×. The most-recommended bar in Mk5 threads.", "price": "$290", "signal": "Forum favorite", "links": [{"store": "Neuspeed", "url": "https://neuspeed.com/products/neuspeed-anti-sway-bar-rear-25mm-2502253"}]}, {"name": "034Motorsport solid, adjustable", "note": "Solid bar, billet brackets with grease ports, Teflon bushings. Stiffest of the common choices (150%+ over stock).", "price": "$300–350", "signal": "Track-leaning pick", "links": []}, {"name": "H&R 24mm", "note": "Non-adjustable, softer step up. Good if you want less body roll without changing the car's character much.", "price": "$200–250", "signal": "Mild option", "links": []}, {"name": "Whiteline 24mm, adjustable", "note": "Adjustable, well-reviewed, often bundled with their end links.", "price": "$230–280", "signal": "Value pick", "links": []}], "lifespan": {"title": "When owners do this", "headline": ["Usually the first or second handling mod, right after tires"], "earliest": null, "detail": "The stock bar doesn't wear out, so there's no failure mileage. Owners upgrade it when they notice the car pushing wide in fast corners, typically before touching springs or dampers because it's cheaper and reversible.", "factors": ["Sticky summer tires make the understeer more noticeable", "Lowering springs stiffen the front, which increases the case for a rear bar"], "inspect": ["While you're under there: end links and bushings are often tired by 80,000+ miles; replace them if they're loose or cracked"], "confidence": {"level": "community", "n": 4, "note": "Forum consensus on ordering; the end-link mileage is anecdotal."}}}$j$::jsonb, updated_at = now() where id = 'sway-rear';
